class Solution {
public:
    int maxSum(vector<int>& nums1, vector<int>& nums2) {
        const long long MOD = 1e9 + 7;
        unordered_set<int> s1(nums1.begin(), nums1.end());
        vector<int> common;
        for (int x : nums2) if (s1.count(x)) common.push_back(x);
        int n1 = nums1.size(), n2 = nums2.size();
        vector<long long> p1(n1 + 1, 0), p2(n2 + 1, 0);
        for (int i = 0; i < n1; i++) p1[i+1] = p1[i] + nums1[i];
        for (int i = 0; i < n2; i++) p2[i+1] = p2[i] + nums2[i];
        long long ans = 0, prev = 0;
        auto idx = [](vector<int>& a, int v) {
            return upper_bound(a.begin(), a.end(), v) - a.begin();
        };
        for (int c : common) {
            int l1 = idx(nums1, prev), r1 = idx(nums1, c);
            int l2 = idx(nums2, prev), r2 = idx(nums2, c);
            ans += c + max(p1[r1] - p1[l1], p2[r2] - p2[l2]);
            prev = c;
        }
        ans += max(p1[n1] - p1[idx(nums1, prev)], p2[n2] - p2[idx(nums2, prev)]);
        return ans % MOD;
    }
};

