class Solution {
    public int maxSum(int[] nums1, int[] nums2) {
        final long MOD = 1_000_000_007L;
        Set<Integer> s1 = new HashSet<>();
        for (int x : nums1) s1.add(x);
        List<Integer> common = new ArrayList<>();
        for (int x : nums2) if (s1.contains(x)) common.add(x);
        int n1 = nums1.length, n2 = nums2.length;
        long[] p1 = new long[n1 + 1], p2 = new long[n2 + 1];
        for (int i = 0; i < n1; i++) p1[i+1] = p1[i] + nums1[i];
        for (int i = 0; i < n2; i++) p2[i+1] = p2[i] + nums2[i];
        long ans = 0, prev = 0;
        for (int c : common) {
            int l1 = ub(nums1, prev), r1 = ub(nums1, c);
            int l2 = ub(nums2, prev), r2 = ub(nums2, c);
            ans += c + Math.max(p1[r1] - p1[l1], p2[r2] - p2[l2]);
            prev = c;
        }
        ans += Math.max(p1[n1] - p1[ub(nums1, (int) prev)],
                        p2[n2] - p2[ub(nums2, (int) prev)]);
        return (int)(ans % MOD);
    }
    private int ub(int[] a, int v) {
        int lo = 0, hi = a.length;
        while (lo < hi) { int m = (lo + hi) >>> 1; if (a[m] <= v) lo = m + 1; else hi = m; }
        return lo;
    }
}

