var maxSum = function(nums1, nums2) {
    const MOD = 1e9 + 7;
    const s1 = new Set(nums1);
    const common = nums2.filter(x => s1.has(x));
    const p1 = [0], p2 = [0];
    for (const x of nums1) p1.push(p1[p1.length - 1] + x);
    for (const x of nums2) p2.push(p2[p2.length - 1] + x);
    const ub = (arr, v) => {
        let lo = 0, hi = arr.length;
        while (lo < hi) { const m = (lo + hi) >> 1; if (arr[m] <= v) lo = m + 1; else hi = m; }
        return lo;
    };
    let ans = 0, prev = 0;
    for (const c of common) {
        const l1 = ub(nums1, prev), r1 = ub(nums1, c);
        const l2 = ub(nums2, prev), r2 = ub(nums2, c);
        ans += c + Math.max(p1[r1] - p1[l1], p2[r2] - p2[l2]);
        prev = c;
    }
    ans += Math.max(p1[p1.length - 1] - p1[ub(nums1, prev)],
                    p2[p2.length - 1] - p2[ub(nums2, prev)]);
    return ans % MOD;
};

