class Solution:
    def maxSum(self, nums1: List[int], nums2: List[int]) -> int:
        MOD = 10**9 + 7
        i = j = 0
        acc1 = acc2 = total = 0
        n1, n2 = len(nums1), len(nums2)
        while i < n1 or j < n2:
            if i < n1 and (j == n2 or nums1[i] < nums2[j]):
                acc1 += nums1[i]; i += 1
            elif j < n2 and (i == n1 or nums1[i] > nums2[j]):
                acc2 += nums2[j]; j += 1
            else:
                total += max(acc1, acc2) + nums1[i]
                acc1 = acc2 = 0
                i += 1; j += 1
        total += max(acc1, acc2)
        return total % MOD

